package main

import (
	"bufio"
	"encoding/csv"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"sync"
)

const Version = "3.7.0"

// Language represents a programming language and its properties
type Language struct {
	Name       string
	Extensions []string
	LineComment string
	MultilineCommentStart string
	MultilineCommentEnd string
	Strings []string
}

// FileStats represents stats for a single file
type FileStats struct {
	Path      string
	Language  string
	Lines     int
	Code      int
	Comment   int
	Blank     int
	Complexity int
	Bytes     int64
}

// LanguageStats represents aggregated stats for a language
type LanguageStats struct {
	Name                string
	Files               int
	Lines               int
	Code                int
	Comment             int
	Blank               int
	Complexity          int
	Bytes               int64
	WeightedComplexity  int
	FileList            []string
	ULOC                int
}

// Options represents command line options
type Options struct {
	Format              string
	OutputFile          string
	ByFile              bool
	Wide                bool
	NoComplexity        bool
	AvgWage             int
	CurrencySymbol      string
	Verbose             bool
	Debug               bool
	Languages           bool
	Version             bool
	Help                bool
	NoLarge             bool
	LargeLineCount      int
	LargeByteCount      int
	ExcludeDir          []string
	ExcludeExt          []string
	ExcludeFile         []string
	IncludeExt          []string
	NotMatch            []string
	Sort                string
	FileProcessWorkers  int
	DirectoryWalkerWorkers int
	NoGitignore         bool
	PercentageValues    bool
	DRYness             bool
	ULOC                bool
	CI                  bool
	Percent             bool
	NoCocomo            bool
	Count               bool
	Character           bool
	ByFile2             bool
	Complexity          bool
	Wide2               bool
	SizeUnit            string
	AvgWageVal          int
	EAF                 float64
	Overhead            float64
	CocomoProjectType   string
	CountAs             string
	CountIgnore         bool
	Gen                 bool
	GeneratedMarkers    []string
	Min                 bool
	Trace               bool
	NotMatchRegex       *regexp.Regexp
}

var (
	languageMap = map[string]*Language{}
	mu           sync.Mutex
)

func init() {
	initLanguages()
}

func initLanguages() {
	languages := []Language{
		{
			Name:       "Go",
			Extensions: []string{".go"},
			LineComment: "//",
			MultilineCommentStart: "/*",
			MultilineCommentEnd: "*/",
			Strings: []string{"\"", "`"},
		},
		{
			Name:       "Python",
			Extensions: []string{".py"},
			LineComment: "#",
			Strings: []string{"\"", "'", "\"\"\"", "'''"},
		},
		{
			Name:       "C",
			Extensions: []string{".c", ".h"},
			LineComment: "//",
			MultilineCommentStart: "/*",
			MultilineCommentEnd: "*/",
			Strings: []string{"\"", "'"},
		},
		{
			Name:       "Java",
			Extensions: []string{".java"},
			LineComment: "//",
			MultilineCommentStart: "/*",
			MultilineCommentEnd: "*/",
			Strings: []string{"\"", "'"},
		},
		// Add more languages as needed
	}

	for _, lang := range languages {
		for _, ext := range lang.Extensions {
			languageMap[ext] = &lang
		}
	}
}

func getLanguageByExtension(filename string) *Language {
	ext := filepath.Ext(filename)
	if lang, ok := languageMap[ext]; ok {
		return lang
	}
	return nil
}

func countLines(path string, lang *Language) (lines, code, comment, blank int, err error) {
	file, err := os.Open(path)
	if err != nil {
		return
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	inMultilineComment := false

	for scanner.Scan() {
		line := scanner.Text()
		trimmed := strings.TrimSpace(line)
		lines++

		if trimmed == "" {
			blank++
			continue
		}

		// Check for multiline comment start/end
		if lang.MultilineCommentStart != "" {
			if strings.Contains(line, lang.MultilineCommentStart) {
				inMultilineComment = true
			}
			if inMultilineComment {
				comment++
				if strings.Contains(line, lang.MultilineCommentEnd) {
					inMultilineComment = false
				}
				continue
			}
		}

		// Check for single line comment
		if lang.LineComment != "" && strings.Contains(trimmed, lang.LineComment) {
			idx := strings.Index(trimmed, lang.LineComment)
			if idx == 0 {
				comment++
				continue
			}
		}

		code++
	}

	return
}

func processFile(path string, opts *Options) (*FileStats, error) {
	info, err := os.Stat(path)
	if err != nil {
		return nil, err
	}

	lang := getLanguageByExtension(path)
	if lang == nil {
		return nil, nil
	}

	lines, code, comment, blank, err := countLines(path, lang)
	if err != nil {
		return nil, err
	}

	return &FileStats{
		Path:       path,
		Language:   lang.Name,
		Lines:      lines,
		Code:       code,
		Comment:    comment,
		Blank:      blank,
		Complexity: 0,
		Bytes:      info.Size(),
	}, nil
}

func walkDirectory(dir string, opts *Options) ([]FileStats, error) {
	var stats []FileStats
	var mu sync.Mutex

	err := filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}

		if info.IsDir() {
			if shouldExcludeDir(info.Name(), opts.ExcludeDir) {
				return filepath.SkipDir
			}
			return nil
		}

		if shouldExcludeFile(info.Name(), opts.ExcludeFile) {
			return nil
		}

		fileStat, err := processFile(path, opts)
		if err != nil {
			if opts.Debug {
				fmt.Fprintf(os.Stderr, "Error processing %s: %v\n", path, err)
			}
			return nil
		}

		if fileStat != nil {
			mu.Lock()
			stats = append(stats, *fileStat)
			mu.Unlock()
		}

		return nil
	})

	return stats, err
}

func shouldExcludeDir(name string, excludeDirs []string) bool {
	for _, exc := range excludeDirs {
		if name == exc {
			return true
		}
	}
	return false
}

func shouldExcludeFile(name string, excludeFiles []string) bool {
	for _, exc := range excludeFiles {
		if name == exc {
			return true
		}
	}
	return false
}

func aggregateStats(fileStats []FileStats) map[string]*LanguageStats {
	result := make(map[string]*LanguageStats)

	for _, fs := range fileStats {
		if _, ok := result[fs.Language]; !ok {
			result[fs.Language] = &LanguageStats{
				Name: fs.Language,
			}
		}

		ls := result[fs.Language]
		ls.Files++
		ls.Lines += fs.Lines
		ls.Code += fs.Code
		ls.Comment += fs.Comment
		ls.Blank += fs.Blank
		ls.Complexity += fs.Complexity
		ls.Bytes += fs.Bytes
		ls.FileList = append(ls.FileList, fs.Path)
	}

	return result
}

func calculateCOCOMO(totalCode int, cocomoType string, avgWage int, eaf float64, overhead float64) (cost float64, effort float64, people float64) {
	kloc := float64(totalCode) / 1000.0

	var a, b float64
	switch cocomoType {
	case "organic":
		a = 2.4
		b = 1.05
	case "semi-detached":
		a = 3.0
		b = 1.12
	case "embedded":
		a = 3.6
		b = 1.20
	default:
		a = 2.4
		b = 1.05
	}

	effort = a * (kloc * kloc * b) * eaf
	people = effort / 3.0
	cost = effort * float64(avgWage) * overhead

	return
}

func formatTabular(stats map[string]*LanguageStats, opts *Options) string {
	var output strings.Builder

	// Sort languages
	var langs []string
	for lang := range stats {
		langs = append(langs, lang)
	}
	sort.Strings(langs)

	// Print header
	output.WriteString("───────────────────────────────────────────────────────────────────────────────\n")
	output.WriteString(fmt.Sprintf("%-20s %10s %10s %10s %10s %10s %10s\n",
		"Language", "Files", "Lines", "Blanks", "Comments", "Code", "Complexity"))
	output.WriteString("───────────────────────────────────────────────────────────────────────────────\n")

	totalFiles := 0
	totalLines := 0
	totalBlanks := 0
	totalComments := 0
	totalCode := 0
	totalComplexity := 0

	for _, lang := range langs {
		ls := stats[lang]
		totalFiles += ls.Files
		totalLines += ls.Lines
		totalBlanks += ls.Blank
		totalComments += ls.Comment
		totalCode += ls.Code
		totalComplexity += ls.Complexity

		output.WriteString(fmt.Sprintf("%-20s %10d %10d %10d %10d %10d %10d\n",
			ls.Name, ls.Files, ls.Lines, ls.Blank, ls.Comment, ls.Code, ls.Complexity))
	}

	output.WriteString("───────────────────────────────────────────────────────────────────────────────\n")
	output.WriteString(fmt.Sprintf("%-20s %10d %10d %10d %10d %10d %10d\n",
		"Total", totalFiles, totalLines, totalBlanks, totalComments, totalCode, totalComplexity))
	output.WriteString("───────────────────────────────────────────────────────────────────────────────\n")

	// COCOMO calculations
	if !opts.NoCocomo {
		cost, effort, people := calculateCOCOMO(totalCode, opts.CocomoProjectType, opts.AvgWage, opts.EAF, opts.Overhead)
		output.WriteString(fmt.Sprintf("Estimated Cost to Develop (%s) %s%.0f\n", opts.CocomoProjectType, opts.CurrencySymbol, cost))
		output.WriteString(fmt.Sprintf("Estimated Schedule Effort (%s) %.2f months\n", opts.CocomoProjectType, effort))
		output.WriteString(fmt.Sprintf("Estimated People Required (%s) %.2f\n", opts.CocomoProjectType, people))
	}

	output.WriteString("───────────────────────────────────────────────────────────────────────────────\n")

	return output.String()
}

func formatJSON(stats map[string]*LanguageStats, opts *Options) string {
	var result []interface{}
	for _, ls := range stats {
		result = append(result, map[string]interface{}{
			"Name":                ls.Name,
			"Files":               ls.Files,
			"Lines":               ls.Lines,
			"Blank":               ls.Blank,
			"Comments":            ls.Comment,
			"Code":                ls.Code,
			"Complexity":          ls.Complexity,
			"Bytes":               ls.Bytes,
			"WeightedComplexity":  ls.WeightedComplexity,
			"LineLength":          nil,
			"ULOC":                ls.ULOC,
		})
	}
	data, _ := json.Marshal(result)
	return string(data)
}

func formatCSV(stats map[string]*LanguageStats, opts *Options) string {
	var output strings.Builder

	writer := csv.NewWriter(&output)
	writer.Write([]string{"Language", "Lines", "Code", "Comments", "Blanks", "Complexity", "Bytes", "Files", "ULOC"})

	var langs []string
	for lang := range stats {
		langs = append(langs, lang)
	}
	sort.Strings(langs)

	for _, lang := range langs {
		ls := stats[lang]
		writer.Write([]string{
			ls.Name,
			fmt.Sprintf("%d", ls.Lines),
			fmt.Sprintf("%d", ls.Code),
			fmt.Sprintf("%d", ls.Comment),
			fmt.Sprintf("%d", ls.Blank),
			fmt.Sprintf("%d", ls.Complexity),
			fmt.Sprintf("%d", ls.Bytes),
			fmt.Sprintf("%d", ls.Files),
			fmt.Sprintf("%d", ls.ULOC),
		})
	}

	writer.Flush()
	return output.String()
}

func printLanguages() {
	var exts []string
	seen := make(map[string]bool)
	for ext := range languageMap {
		if !seen[ext] {
			exts = append(exts, ext)
			seen[ext] = true
		}
	}
	sort.Strings(exts)

	for ext, lang := range languageMap {
		fmt.Printf("%s (%s)\n", lang.Name, strings.TrimPrefix(ext, "."))
	}
}

func main() {
	opts := &Options{
		Format:                 "tabular",
		AvgWage:                56286,
		CurrencySymbol:         "$",
		ExcludeDir:             []string{".git", ".hg", ".svn"},
		ExcludeFile:            []string{"package-lock.json", "Cargo.lock", "yarn.lock", "pubspec.lock", "Podfile.lock", "pnpm-lock.yaml"},
		FileProcessWorkers:     192,
		DirectoryWalkerWorkers: 8,
		LargeLineCount:         40000,
		LargeByteCount:         1000000,
		EAF:                    1.0,
		Overhead:               2.4,
		CocomoProjectType:      "organic",
	}

	flag.StringVar(&opts.Format, "f", "tabular", "output format")
	flag.StringVar(&opts.Format, "format", "tabular", "output format")
	flag.BoolVar(&opts.ByFile, "by-file", false, "display output for every file")
	flag.BoolVar(&opts.Wide, "w", false, "wider output")
	flag.BoolVar(&opts.Wide, "wide", false, "wider output")
	flag.BoolVar(&opts.NoComplexity, "c", false, "skip complexity")
	flag.BoolVar(&opts.NoComplexity, "no-complexity", false, "skip complexity")
	flag.IntVar(&opts.AvgWage, "avg-wage", 56286, "average wage")
	flag.StringVar(&opts.CurrencySymbol, "currency-symbol", "$", "currency symbol")
	flag.BoolVar(&opts.Verbose, "v", false, "verbose")
	flag.BoolVar(&opts.Verbose, "verbose", false, "verbose")
	flag.BoolVar(&opts.Debug, "debug", false, "debug")
	flag.BoolVar(&opts.Languages, "l", false, "list languages")
	flag.BoolVar(&opts.Languages, "languages", false, "list languages")
	flag.BoolVar(&opts.Version, "version", false, "version")
	flag.BoolVar(&opts.Help, "h", false, "help")
	flag.BoolVar(&opts.Help, "help", false, "help")
	flag.StringVar(&opts.OutputFile, "o", "", "output file")
	flag.StringVar(&opts.OutputFile, "output", "", "output file")
	flag.StringVar(&opts.Sort, "s", "files", "sort by")
	flag.StringVar(&opts.Sort, "sort", "files", "sort by")

	flag.Parse()

	if opts.Help {
		fmt.Println("Usage: scc [flags] [files or directories]")
		flag.PrintDefaults()
		os.Exit(0)
	}

	if opts.Version {
		fmt.Printf("scc version %s\n", Version)
		os.Exit(0)
	}

	if opts.Languages {
		printLanguages()
		os.Exit(0)
	}

	paths := flag.Args()
	if len(paths) == 0 {
		paths = []string{"."}
	}

	var allStats []FileStats
	for _, path := range paths {
		info, err := os.Stat(path)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}

		if info.IsDir() {
			stats, err := walkDirectory(path, opts)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				os.Exit(1)
			}
			allStats = append(allStats, stats...)
		} else {
			stat, err := processFile(path, opts)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				os.Exit(1)
			}
			if stat != nil {
				allStats = append(allStats, *stat)
			}
		}
	}

	aggregated := aggregateStats(allStats)

	var output string
	switch opts.Format {
	case "json":
		output = formatJSON(aggregated, opts)
	case "csv":
		output = formatCSV(aggregated, opts)
	case "tabular", "wide":
		output = formatTabular(aggregated, opts)
	default:
		output = formatTabular(aggregated, opts)
	}

	if opts.OutputFile != "" {
		if err := os.WriteFile(opts.OutputFile, []byte(output), 0644); err != nil {
			fmt.Fprintf(os.Stderr, "Error writing output: %v\n", err)
			os.Exit(1)
		}
	} else {
		fmt.Print(output)
	}
}
EOF

