		os.Exit(0)
	}

	if opts.Languages {
		printLanguages()
		os.Exit(0)
	}

	paths := flag.Args()
	if len(paths) == 0 {
		paths = []string{"."}
	}

	var allStats []FileStats
	for _, path := range paths {
		info, err := os.Stat(path)
		if err != nil {
