package main

import (
	"bufio"
	"os"
	"strings"
)

// FileStatistics holds line count statistics for a file
type FileStatistics struct {
	FilePath   string
	Language   string
	Lines      int
	Code       int
	Comments   int
	Blanks     int
	Complexity int
	Bytes      int64
}

// CountLines counts the lines in a file
func CountLines(filePath string) (*FileStatistics, error) {
	file, err := os.Open(filePath)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	fileInfo, err := os.Stat(filePath)
	if err != nil {
		return nil, err
	}

	language := getLanguage(fileInfo.Name())
	if language == nil {
		return nil, nil
	}

	stat := &FileStatistics{
		FilePath: filePath,
		Language: language.Name,
		Bytes:    fileInfo.Size(),
	}

	scanner := bufio.NewScanner(file)
	inMultilineComment := false

	for scanner.Scan() {
		line := scanner.Text()
		stat.Lines++
		trimmed := strings.TrimSpace(line)

		// Empty line
		if len(trimmed) == 0 {
			stat.Blanks++
			continue
		}

		// Check for multiline comments
		if language.MultiLineCommentStart != "" {
			if inMultilineComment {
				stat.Comments++
				if strings.Contains(trimmed, language.MultiLineCommentEnd) {
					inMultilineComment = false
				}
				continue
			}

			if strings.Contains(trimmed, language.MultiLineCommentStart) {
				// Check if it's also closed on the same line
				if strings.Index(trimmed, language.MultiLineCommentStart) < strings.Index(trimmed, language.MultiLineCommentEnd) &&
					strings.Contains(trimmed, language.MultiLineCommentEnd) {
					// Single line comment
					stat.Comments++
					continue
				}
				inMultilineComment = true
				stat.Comments++
				if strings.Contains(trimmed, language.MultiLineCommentEnd) {
					inMultilineComment = false
				}
				continue
			}
		}

		// Check for line comments
		if language.LineComment != "" {
			idx := strings.Index(trimmed, language.LineComment)
			if idx != -1 {
				// Make sure it's not in a string
				if !isInString(trimmed, idx) {
					// This is a tricky part - we need to check if the whole line is a comment
					beforeComment := trimmed[:idx]
					if strings.TrimSpace(beforeComment) == "" {
						stat.Comments++
						continue
					}
				}
			}
		}

		stat.Code++
	}

	return stat, nil
}

func isInString(line string, pos int) bool {
	// Simple heuristic: count quotes before position
	singleQuotes := 0
	doubleQuotes := 0

	for i := 0; i < pos && i < len(line); i++ {
		if line[i] == '\'' && (i == 0 || line[i-1] != '\\') {
			singleQuotes++
		} else if line[i] == '"' && (i == 0 || line[i-1] != '\\') {
			doubleQuotes++
		}
	}

	return (singleQuotes%2 == 1) || (doubleQuotes%2 == 1)
}
