// AggregatedStats holds statistics for a language
type AggregatedStats struct {
	Language            string
	Files               int
	Lines               int
	Code                int
	Comments            int
	Blanks              int
	Complexity          int
	Bytes               int64
	WeightedComplexity  int
	ULOC                int
	FileList            []string
}

// OutputOptions holds output formatting options
type OutputOptions struct {
	Format                   string
	OutputFile               string
	ByFile                   bool
	Wide                     bool
	NoComplexity             bool
	AvgWage                  int
	CurrencySymbol           string
	Verbose                  bool
	Debug                    bool
	NoLarge                  bool
	LargeLineCount           int
	LargeByteCount           int
	ExcludeDir               []string
	ExcludeExt               []string
	ExcludeFile              []string
	IncludeExt               []string
