func walkDirectory(dir string, opts *OutputOptions) ([]*FileStatistics, error) {
	var results []*FileStatistics

	err := filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}

		if info.IsDir() {
			// Skip excluded directories
			for _, exc := range opts.ExcludeDir {
				if info.Name() == exc {
					return filepath.SkipDir
				}
			}
			return nil
		}

		// Skip excluded files
		for _, exc := range opts.ExcludeFile {
			if info.Name() == exc {
				return nil
			}
		}

		stat, err := CountLines(path)
		if err != nil {
			if opts.Debug {
				fmt.Fprintf(os.Stderr, "Error processing %s: %v\n", path, err)
			}
			return nil
		}

		if stat != nil {
			results = append(results, stat)
		}

		return nil
	})

	return results, err
}

func aggregateStats(fileStats []*FileStatistics) map[string]*AggregatedStats {
	result := make(map[string]*AggregatedStats)

	for _, fs := range fileStats {
		if _, ok := result[fs.Language]; !ok {
			result[fs.Language] = &AggregatedStats{
				Language: fs.Language,
			}
		}

		agg := result[fs.Language]
		agg.Files++
		agg.Lines += fs.Lines
		agg.Code += fs.Code
		agg.Comments += fs.Comments
		agg.Blanks += fs.Blanks
		agg.Complexity += fs.Complexity
		agg.Bytes += fs.Bytes
		agg.FileList = append(agg.FileList, fs.FilePath)
	}

	return result
}

func calculateCOCOMO(totalCode int, cocomoType string, avgWage int, eaf float64, overhead float64) (float64, float64, float64) {
	kloc := float64(totalCode) / 1000.0

	var a, b float64
	switch cocomoType {
	case "organic":
		a = 2.4
		b = 1.05
	case "semi-detached":
		a = 3.0
		b = 1.12
	case "embedded":
		a = 3.6
		b = 1.20
	default:
		a = 2.4
		b = 1.05
	}

	effort := a * kloc * (kloc * b) * eaf
	people := effort / 3.0
	cost := effort * float64(avgWage) * overhead

	return cost, effort, people
}

func formatTabular(aggregated map[string]*AggregatedStats, fileStats []*FileStatistics, opts *OutputOptions) string {
	var output strings.Builder

	// Sort languages
	var langs []string
	for lang := range aggregated {
		langs = append(langs, lang)
	}
	sort.Strings(langs)

	// Calculate totals
	totalFiles := 0
	totalLines := 0
	totalBlanks := 0
	totalComments := 0
	totalCode := 0
	totalComplexity := 0
	totalBytes := int64(0)

	for _, agg := range aggregated {
		totalFiles += agg.Files
		totalLines += agg.Lines
		totalBlanks += agg.Blanks
		totalComments += agg.Comments
		totalCode += agg.Code
		totalComplexity += agg.Complexity
		totalBytes += agg.Bytes
	}

	// Print header
	output.WriteString("───────────────────────────────────────────────────────────────────────────────\n")
	if opts.Wide {
		output.WriteString(fmt.Sprintf("%-30s %10s %10s %10s %10s %10s %10s %10s\n",
			"Language", "Files", "Lines", "Blanks", "Comments", "Code", "Complexity", "Cmplx/Lines"))
	} else {
		output.WriteString(fmt.Sprintf("%-20s %10s %10s %10s %10s %10s %10s\n",
			"Language", "Files", "Lines", "Blanks", "Comments", "Code", "Complexity"))
	}
	output.WriteString("───────────────────────────────────────────────────────────────────────────────\n")

	// Print language stats
	for _, lang := range langs {
		agg := aggregated[lang]
		if opts.Wide {
			cmplxPerLine := 0.0
			if agg.Lines > 0 {
				cmplxPerLine = float64(agg.Complexity) / float64(agg.Lines)
			}
			output.WriteString(fmt.Sprintf("%-30s %10d %10d %10d %10d %10d %10d %10.2f\n",
				agg.Language, agg.Files, agg.Lines, agg.Blanks, agg.Comments, agg.Code, agg.Complexity, cmplxPerLine))
		} else {
			output.WriteString(fmt.Sprintf("%-20s %10d %10d %10d %10d %10d %10d\n",
				agg.Language, agg.Files, agg.Lines, agg.Blanks, agg.Comments, agg.Code, agg.Complexity))
		}

		// Print by-file stats if requested
		if opts.ByFile {
			for _, filePath := range agg.FileList {
				// Find the file stats
				for _, fs := range fileStats {
					if fs.FilePath == filePath {
						if opts.Wide {
							output.WriteString(fmt.Sprintf("%-30s %10d %10d %10d %10d %10d\n",
								filePath, fs.Lines, fs.Blanks, fs.Comments, fs.Code, fs.Complexity))
						} else {
							output.WriteString(fmt.Sprintf("%s %10d %10d %10d %10d %10d\n",
								filePath, fs.Lines, fs.Blanks, fs.Comments, fs.Code, fs.Complexity))
						}
						break
					}
				}
			}
		}
	}

	// Print total
	output.WriteString("───────────────────────────────────────────────────────────────────────────────\n")
	if opts.Wide {
		cmplxPerLine := 0.0
		if totalLines > 0 {
			cmplxPerLine = float64(totalComplexity) / float64(totalLines)
		}
		output.WriteString(fmt.Sprintf("%-30s %10d %10d %10d %10d %10d %10d %10.2f\n",
			"Total", totalFiles, totalLines, totalBlanks, totalComments, totalCode, totalComplexity, cmplxPerLine))
	} else {
		output.WriteString(fmt.Sprintf("%-20s %10d %10d %10d %10d %10d %10d\n",
			"Total", totalFiles, totalLines, totalBlanks, totalComments, totalCode, totalComplexity))
	}
	output.WriteString("───────────────────────────────────────────────────────────────────────────────\n")

	// COCOMO calculations
	if !opts.NoCocomo {
		cost, effort, people := calculateCOCOMO(totalCode, opts.CocomoProjectType, opts.AvgWage, opts.EAF, opts.Overhead)
		output.WriteString(fmt.Sprintf("Estimated Cost to Develop (%s) %s%.0f\n", opts.CocomoProjectType, opts.CurrencySymbol, cost))
		output.WriteString(fmt.Sprintf("Estimated Schedule Effort (%s) %.2f months\n", opts.CocomoProjectType, effort))
		output.WriteString(fmt.Sprintf("Estimated People Required (%s) %.2f\n", opts.CocomoProjectType, people))
	}

	output.WriteString("───────────────────────────────────────────────────────────────────────────────\n")

	// File size info
	sizeStr := formatBytes(totalBytes)
	output.WriteString(fmt.Sprintf("Processed %d bytes, %.3f megabytes (SI)\n", totalBytes, float64(totalBytes)/1000000.0))
	output.WriteString("───────────────────────────────────────────────────────────────────────────────\n")

	return output.String()
}

func formatBytes(bytes int64) string {
	if bytes < 1000 {
		return fmt.Sprintf("%d B", bytes)
	} else if bytes < 1000000 {
		return fmt.Sprintf("%.2f KB", float64(bytes)/1000)
	}
	return fmt.Sprintf("%.3f MB", float64(bytes)/1000000)
}

