	flag.BoolVar(&opts.Verbose, "verbose", false, "verbose")
	flag.BoolVar(&opts.Debug, "debug", false, "debug")
	flag.BoolVar(&opts.NoCocomo, "no-cocomo", false, "skip COCOMO")
	flag.StringVar(&opts.Sort, "s", "files", "sort by column")
	flag.StringVar(&opts.Sort, "sort", "files", "sort by column")
	flag.StringVar(&opts.CocomoProjectType, "cocomo-project-type", "organic", "COCOMO project type")
	flag.Float64Var(&opts.EAF, "eaf", 1.0, "effort adjustment factor")
	flag.Float64Var(&opts.Overhead, "overhead", 2.4, "overhead multiplier")
	flag.IntVar(&opts.LargeLineCount, "large-line-count", 40000, "large line count")
	flag.IntVar(&opts.LargeByteCount, "large-byte-count", 1000000, "large byte count")
	flag.BoolVar(&opts.NoLarge, "no-large", false, "ignore large files")
	flag.BoolVar(&opts.ULOC, "u", false, "calculate ULOC")
	flag.BoolVar(&opts.ULOC, "uloc", false, "calculate ULOC")
	flag.BoolVar(&opts.DRYness, "a", false, "calculate DRYness")
	flag.BoolVar(&opts.DRYness, "dryness", false, "calculate DRYness")
	flag.BoolVar(&opts.Character, "m", false, "calculate characters")
	flag.BoolVar(&opts.Character, "character", false, "calculate characters")
	flag.BoolVar(&opts.PercentageValues, "p", false, "include percentage values")
	flag.BoolVar(&opts.PercentageValues, "percent", false, "include percentage values")
	flag.BoolVar(&opts.CI, "ci", false, "CI output settings")
	flag.BoolVar(&opts.CountIgnore, "count-ignore", false, "count .gitignore files")
	flag.BoolVar(&opts.Min, "min", false, "identify minified files")
	flag.BoolVar(&opts.Gen, "gen", false, "identify generated files")
	flag.BoolVar(&opts.NoMin, "no-min", false, "exclude minified files")
	flag.BoolVar(&opts.NoGen, "no-gen", false, "exclude generated files")
	flag.BoolVar(&opts.NoMinGen, "no-min-gen", false, "exclude minified/generated files")
	flag.StringVar(&opts.SizeUnit, "size-unit", "si", "size unit")

	// Handle --help and --version specially
	versionFlag := flag.Bool("version", false, "print version")
	helpFlag := flag.Bool("h", false, "print help")

