package main

import (
	"bufio"
	"os"
	"strings"
)

// FileStatistics holds line count statistics for a file
type FileStatistics struct {
	FilePath   string
	Language   string
	Lines      int
	Code       int
	Comments   int
	Blanks     int
	Complexity int
	Bytes      int64
}

// CountLines counts the lines in a file
func CountLines(filePath string) (*FileStatistics, error) {
	file, err := os.Open(filePath)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	fileInfo, err := os.Stat(filePath)
	if err != nil {
		return nil, err
	}

	language := getLanguage(fileInfo.Name())
	if language == nil {
		return nil, nil
	}

	stat := &FileStatistics{
		FilePath: filePath,
		Language: language.Name,
		Bytes:    fileInfo.Size(),
	}

	scanner := bufio.NewScanner(file)
	inMultilineComment := false
	var multilineCommentEnd string

	for scanner.Scan() {
		line := scanner.Text()
		stat.Lines++
		trimmed := strings.TrimSpace(line)

		// Empty line
		if len(trimmed) == 0 {
			stat.Blanks++
			continue
		}

		// Check for Python triple quotes
		if language.Name == "Python" && !inMultilineComment {
			if strings.HasPrefix(trimmed, `"""`) || strings.HasPrefix(trimmed, "'''") {
				marker := `"""`
				if strings.HasPrefix(trimmed, "'''") {
					marker = "'''"
				}
				// Count as comment
				stat.Comments++
				// Check if it ends on the same line
				rest := trimmed[3:]
				if !strings.Contains(rest, marker) {
					inMultilineComment = true
					multilineCommentEnd = marker
				}
				continue
			}
		}

		// Check for in-progress multiline comment
		if inMultilineComment {
			stat.Comments++
			if strings.Contains(trimmed, multilineCommentEnd) {
				inMultilineComment = false
			}
			continue
		}

		// Check for multiline comments (C-style)
		if language.MultiLineCommentStart != "" && !inMultilineComment {
			if strings.Contains(trimmed, language.MultiLineCommentStart) {
				// Check if it's also closed on the same line
				startIdx := strings.Index(trimmed, language.MultiLineCommentStart)
				endIdx := strings.Index(trimmed, language.MultiLineCommentEnd)

				if endIdx > startIdx && endIdx != -1 {
					// Both start and end on same line
					stat.Comments++
					continue
				}

				// Starts but doesn't end
				inMultilineComment = true
				multilineCommentEnd = language.MultiLineCommentEnd
				stat.Comments++
				continue
			}
		}

		// Already in multiline comment
		if inMultilineComment {
			stat.Comments++
			if strings.Contains(trimmed, multilineCommentEnd) {
				inMultilineComment = false
			}
			continue
		}

		// Check for line comments
		if language.LineComment != "" {
			idx := strings.Index(trimmed, language.LineComment)
			if idx != -1 {
				// Make sure it's not in a string
				if !isInString(trimmed, idx) {
					// Check if the whole line is a comment
					beforeComment := trimmed[:idx]
					if strings.TrimSpace(beforeComment) == "" {
						stat.Comments++
						continue
					}
				}
			}
		}

		stat.Code++
	}

	return stat, nil
}

func isInString(line string, pos int) bool {
	// Simple heuristic: count quotes before position
	singleQuotes := 0
	doubleQuotes := 0
	escaped := false

	for i := 0; i < pos && i < len(line); i++ {
		if escaped {
			escaped = false
			continue
		}

		if line[i] == '\\' {
			escaped = true
		} else if line[i] == '\'' {
			singleQuotes++
		} else if line[i] == '"' {
			doubleQuotes++
		}
	}

	return (singleQuotes%2 == 1) || (doubleQuotes%2 == 1)
}
