	flag.StringVar(&opts.CocomoProjectType, "cocomo-project-type", "organic", "COCOMO project type")
	flag.Float64Var(&opts.EAF, "eaf", 1.0, "effort adjustment factor")
	flag.Float64Var(&opts.Overhead, "overhead", 2.4, "overhead multiplier")
	flag.IntVar(&opts.LargeLineCount, "large-line-count", 40000, "large line count")
	flag.IntVar(&opts.LargeByteCount, "large-byte-count", 1000000, "large byte count")
	flag.BoolVar(&opts.NoLarge, "no-large", false, "ignore large files")
	flag.BoolVar(&opts.ULOC, "u", false, "calculate ULOC")
	flag.BoolVar(&opts.ULOC, "uloc", false, "calculate ULOC")
	flag.BoolVar(&opts.DRYness, "a", false, "calculate DRYness")
	flag.BoolVar(&opts.DRYness, "dryness", false, "calculate DRYness")
	flag.BoolVar(&opts.Character, "m", false, "calculate characters")
	flag.BoolVar(&opts.Character, "character", false, "calculate characters")
	flag.BoolVar(&opts.PercentageValues, "p", false, "include percentage values")
	flag.BoolVar(&opts.PercentageValues, "percent", false, "include percentage values")
	flag.BoolVar(&opts.CI, "ci", false, "CI output settings")
	flag.BoolVar(&opts.CountIgnore, "count-ignore", false, "count .gitignore files")
	flag.BoolVar(&opts.Min, "min", false, "identify minified files")
	flag.BoolVar(&opts.Gen, "gen", false, "identify generated files")
	flag.BoolVar(&opts.NoMin, "no-min", false, "exclude minified files")
	flag.BoolVar(&opts.NoGen, "no-gen", false, "exclude generated files")
	flag.BoolVar(&opts.NoMinGen, "no-min-gen", false, "exclude minified/generated files")
	flag.StringVar(&opts.SizeUnit, "size-unit", "si", "size unit")
	flag.BoolVar(&opts.ListLanguages, "l", false, "list languages")
	flag.BoolVar(&opts.ListLanguages, "languages", false, "list languages")
	flag.BoolVar(&opts.ShowVersion, "version", false, "show version")

	// Handle --help specially
	helpFlag := flag.Bool("h", false, "show help")
	helpFlag2 := flag.Bool("help", false, "show help")

	flag.Parse()

	if *helpFlag || *helpFlag2 {
		printHelp()
		os.Exit(0)
	}

	if opts.ShowVersion {
		fmt.Printf("scc version %s\n", Version)
		os.Exit(0)
	}

	if opts.ListLanguages {
		printLanguages()
		os.Exit(0)
	}

	paths := flag.Args()
	if len(paths) == 0 {
		paths = []string{"."}
	}

	// Process files
	var allStats []*FileStatistics

	for _, path := range paths {
		info, err := os.Stat(path)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}

		if info.IsDir() {
			stats, err := walkDirectory(path, opts)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				os.Exit(1)
			}
			allStats = append(allStats, stats...)
		} else {
			stat, err := CountLines(path)
			if err != nil {
				if opts.Debug {
					fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				}
			}
			if stat != nil {
				allStats = append(allStats, stat)
			}
		}
	}

	// Aggregate statistics
	aggregated := aggregateStats(allStats)

	// Generate output
	var output string
	switch opts.Format {
	case "json":
		output = formatJSON(aggregated, opts)
	case "json2":
		output = formatJSON2(aggregated, opts)
	case "csv":
		output = formatCSV(aggregated, opts)
	case "csv-stream":
		output = formatCSVStream(aggregated, opts)
	case "cloc-yaml":
		output = formatClocYAML(aggregated, opts)
	case "html":
		output = formatHTML(aggregated, opts)
	case "html-table":
		output = formatHTMLTable(aggregated, opts)
	case "sql":
		output = formatSQL(aggregated, opts)
	case "sql-insert":
		output = formatSQLInsert(aggregated, opts)
	case "openmetrics":
		output = formatOpenMetrics(aggregated, opts)
	case "wide":
		opts.Wide = true
		output = formatTabular(aggregated, allStats, opts)
	case "tabular":
		fallthrough
	default:
		output = formatTabular(aggregated, allStats, opts)
	}

	// Write output
	if opts.OutputFile != "" {
		err := os.WriteFile(opts.OutputFile, []byte(output), 0644)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error writing output: %v\n", err)
			os.Exit(1)
		}
	} else {
		fmt.Print(output)
	}
}

func walkDirectory(dir string, opts *OutputOptions) ([]*FileStatistics, error) {
	var results []*FileStatistics

	err := filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}

		if info.IsDir() {
			// Skip excluded directories
			for _, exc := range opts.ExcludeDir {
				if info.Name() == exc {
					return filepath.SkipDir
				}
			}
			return nil
		}

		// Skip excluded files
		for _, exc := range opts.ExcludeFile {
			if info.Name() == exc {
				return nil
			}
		}

		stat, err := CountLines(path)
		if err != nil {
			if opts.Debug {
				fmt.Fprintf(os.Stderr, "Error processing %s: %v\n", path, err)
			}
			return nil
		}

		if stat != nil {
			results = append(results, stat)
		}

		return nil
	})

	return results, err
}

func aggregateStats(fileStats []*FileStatistics) map[string]*AggregatedStats {
	result := make(map[string]*AggregatedStats)

	for _, fs := range fileStats {
		if _, ok := result[fs.Language]; !ok {
			result[fs.Language] = &AggregatedStats{
				Language: fs.Language,
			}
		}

		agg := result[fs.Language]
		agg.Files++
		agg.Lines += fs.Lines
		agg.Code += fs.Code
		agg.Comments += fs.Comments
		agg.Blanks += fs.Blanks
		agg.Complexity += fs.Complexity
		agg.Bytes += fs.Bytes
		agg.FileList = append(agg.FileList, fs.FilePath)
	}

	return result
}

func calculateCOCOMO(totalCode int, cocomoType string, avgWage int, eaf float64, overhead float64) (float64, float64, float64) {
	kloc := float64(totalCode) / 1000.0

	var a, b float64
	switch cocomoType {
	case "organic":
		a = 2.4
		b = 1.05
	case "semi-detached":
		a = 3.0
		b = 1.12
	case "embedded":
		a = 3.6
		b = 1.20
	default:
		a = 2.4
		b = 1.05
	}

	// Calculate effort (person-months)
	MM := a * math.Pow(kloc, b) * eaf

	// Calculate schedule (months)
	schedule := 2.5 * math.Pow(MM, 0.38)

	// Calculate people (person-months / months)
	people := MM / schedule

	// Calculate cost
	cost := MM * (float64(avgWage) / 12.0) * overhead

	return cost, schedule, people
}

func formatTabular(aggregated map[string]*AggregatedStats, fileStats []*FileStatistics, opts *OutputOptions) string {
	var output strings.Builder

	// Sort languages
	var langs []string
	for lang := range aggregated {
		langs = append(langs, lang)
	}
	sort.Strings(langs)

	// Calculate totals
	totalFiles := 0
	totalLines := 0
	totalBlanks := 0
	totalComments := 0
	totalCode := 0
	totalComplexity := 0
	totalBytes := int64(0)

	for _, agg := range aggregated {
		totalFiles += agg.Files
		totalLines += agg.Lines
		totalBlanks += agg.Blanks
		totalComments += agg.Comments
		totalCode += agg.Code
		totalComplexity += agg.Complexity
		totalBytes += agg.Bytes
	}

	// Print header
	output.WriteString("───────────────────────────────────────────────────────────────────────────────\n")
	if opts.Wide {
		output.WriteString(fmt.Sprintf("%-30s %10s %10s %10s %10s %10s %10s %10s\n",
			"Language", "Files", "Lines", "Blanks", "Comments", "Code", "Complexity", "Cmplx/Lines"))
	} else {
		output.WriteString(fmt.Sprintf("%-20s %10s %10s %10s %10s %10s %10s\n",
			"Language", "Files", "Lines", "Blanks", "Comments", "Code", "Complexity"))
	}
	output.WriteString("───────────────────────────────────────────────────────────────────────────────\n")

	// Print language stats
	for _, lang := range langs {
		agg := aggregated[lang]
		if opts.Wide {
			cmplxPerLine := 0.0
			if agg.Lines > 0 {
				cmplxPerLine = float64(agg.Complexity) / float64(agg.Lines)
			}
			output.WriteString(fmt.Sprintf("%-30s %10d %10d %10d %10d %10d %10d %10.2f\n",
				agg.Language, agg.Files, agg.Lines, agg.Blanks, agg.Comments, agg.Code, agg.Complexity, cmplxPerLine))
		} else {
			output.WriteString(fmt.Sprintf("%-20s %10d %10d %10d %10d %10d %10d\n",
				agg.Language, agg.Files, agg.Lines, agg.Blanks, agg.Comments, agg.Code, agg.Complexity))
		}

		// Print by-file stats if requested
		if opts.ByFile {
			for _, filePath := range agg.FileList {
				// Find the file stats
				for _, fs := range fileStats {
					if fs.FilePath == filePath {
						if opts.Wide {
							output.WriteString(fmt.Sprintf("%-30s %10d %10d %10d %10d %10d\n",
								filePath, fs.Lines, fs.Blanks, fs.Comments, fs.Code, fs.Complexity))
						} else {
							output.WriteString(fmt.Sprintf("%s %10d %10d %10d %10d %10d\n",
								filePath, fs.Lines, fs.Blanks, fs.Comments, fs.Code, fs.Complexity))
						}
						break
					}
				}
			}
		}
	}

	// Print total
	output.WriteString("───────────────────────────────────────────────────────────────────────────────\n")
	if opts.Wide {
		cmplxPerLine := 0.0
		if totalLines > 0 {
			cmplxPerLine = float64(totalComplexity) / float64(totalLines)
		}
		output.WriteString(fmt.Sprintf("%-30s %10d %10d %10d %10d %10d %10d %10.2f\n",
			"Total", totalFiles, totalLines, totalBlanks, totalComments, totalCode, totalComplexity, cmplxPerLine))
	} else {
		output.WriteString(fmt.Sprintf("%-20s %10d %10d %10d %10d %10d %10d\n",
			"Total", totalFiles, totalLines, totalBlanks, totalComments, totalCode, totalComplexity))
	}
	output.WriteString("───────────────────────────────────────────────────────────────────────────────\n")

	// COCOMO calculations
	if !opts.NoCocomo {
		cost, schedule, people := calculateCOCOMO(totalCode, opts.CocomoProjectType, opts.AvgWage, opts.EAF, opts.Overhead)
		output.WriteString(fmt.Sprintf("Estimated Cost to Develop (%s) %s%.0f\n", opts.CocomoProjectType, opts.CurrencySymbol, cost))
		output.WriteString(fmt.Sprintf("Estimated Schedule Effort (%s) %.2f months\n", opts.CocomoProjectType, schedule))
		output.WriteString(fmt.Sprintf("Estimated People Required (%s) %.2f\n", opts.CocomoProjectType, people))
	}

	output.WriteString("───────────────────────────────────────────────────────────────────────────────\n")

	// File size info
	output.WriteString(fmt.Sprintf("Processed %d bytes, %.3f megabytes (SI)\n", totalBytes, float64(totalBytes)/1000000.0))
	output.WriteString("───────────────────────────────────────────────────────────────────────────────\n")

	return output.String()
}

func formatJSON(aggregated map[string]*AggregatedStats, opts *OutputOptions) string {
	var result []map[string]interface{}

	var langs []string
	for lang := range aggregated {
		langs = append(langs, lang)
	}
	sort.Strings(langs)

	for _, lang := range langs {
		agg := aggregated[lang]
		result = append(result, map[string]interface{}{
			"Name":               agg.Language,
			"Bytes":              agg.Bytes,
			"CodeBytes":          0,
			"Lines":              agg.Lines,
			"Code":               agg.Code,
			"Comment":            agg.Comments,
			"Blank":              agg.Blanks,
			"Complexity":         agg.Complexity,
			"Count":              agg.Files,
			"WeightedComplexity": agg.WeightedComplexity,
			"Files":              []string{},
			"LineLength":         nil,
			"ULOC":               0,
		})
	}

	data, _ := json.Marshal(result)
	return string(data)
}

