func formatCSV(aggregated map[string]*AggregatedStats, opts *OutputOptions) string {
	var output strings.Builder
	w := csv.NewWriter(&output)

	w.Write([]string{"Language", "Lines", "Code", "Comments", "Blanks", "Complexity", "Bytes", "Files", "ULOC"})

	var langs []string
	for lang := range aggregated {
		langs = append(langs, lang)
	}
	sort.Strings(langs)

	for _, lang := range langs {
		agg := aggregated[lang]
		w.Write([]string{
			agg.Language,
			fmt.Sprintf("%d", agg.Lines),
			fmt.Sprintf("%d", agg.Code),
			fmt.Sprintf("%d", agg.Comments),
			fmt.Sprintf("%d", agg.Blanks),
			fmt.Sprintf("%d", agg.Complexity),
			fmt.Sprintf("%d", agg.Bytes),
			fmt.Sprintf("%d", agg.Files),
			fmt.Sprintf("%d", agg.ULOC),
		})
	}

	w.Flush()
	return output.String()
}

func formatCSVStream(aggregated map[string]*AggregatedStats, opts *OutputOptions) string {
	return formatCSV(aggregated, opts)
}

func formatClocYAML(aggregated map[string]*AggregatedStats, opts *OutputOptions) string {
	var output strings.Builder
	output.WriteString("header:\n  cloc_version: 1.0\n  files_counted: ")

	totalFiles := 0
	for _, agg := range aggregated {
		totalFiles += agg.Files
	}
	output.WriteString(fmt.Sprintf("%d\n", totalFiles))

	var langs []string
	for lang := range aggregated {
		langs = append(langs, lang)
	}
	sort.Strings(langs)

	for _, lang := range langs {
		agg := aggregated[lang]
		output.WriteString(fmt.Sprintf("%s:\n", agg.Language))
		output.WriteString(fmt.Sprintf("  files: %d\n", agg.Files))
		output.WriteString(fmt.Sprintf("  blank: %d\n", agg.Blanks))
		output.WriteString(fmt.Sprintf("  comment: %d\n", agg.Comments))
		output.WriteString(fmt.Sprintf("  code: %d\n", agg.Code))
	}

	return output.String()
}

