			Name:                  "Objective C",
			Extensions:            []string{".m", ".mm"},
			LineComment:           "//",
			MultiLineCommentStart: "/*",
			MultiLineCommentEnd:   "*/",
		},
		{
			Name:                  "Lisp",
			Extensions:            []string{".lisp", ".lsp"},
			LineComment:           ";",
			MultiLineCommentStart: "#|",
			MultiLineCommentEnd:   "|#",
		},
		{
			Name:                  "Scheme",
			Extensions:            []string{".scm"},
			LineComment:           ";",
			MultiLineCommentStart: "#|",
			MultiLineCommentEnd:   "|#",
		},
		{
			Name:                  "Elm",
			Extensions:            []string{".elm"},
			LineComment:           "--",
			MultiLineCommentStart: "{-",
			MultiLineCommentEnd:   "-}",
		},
		{
			Name:                  "Go Module",
			Extensions:            []string{"go.mod", "go.sum"},
			LineComment:           "//",
			MultiLineCommentStart: "/*",
			MultiLineCommentEnd:   "*/",
		},
	}

	for _, lang := range langs {
		for _, ext := range lang.Extensions {
			languages[ext] = lang
		}
	}
}

func getLanguage(filename string) *Language {
	// Check by extension first
	for ext, lang := range languages {
		if strings.HasSuffix(filename, ext) {
			return lang
		}
	}

	// Check by exact name (for Makefile)
	if lang, ok := languages[filename]; ok {
		return lang
	}

	return nil
}
